---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Toast stack: Agent notifications that stack and fan out on hover.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change toast-stack.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './toast-stack.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="toast-stack" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="tsk dm">
  <div class="dm-main"><div class="tsk-stack" aria-live="polite"></div></div>
  <div class="demo"><button class="pill soft sm tsk-add"><svg class="i s"><use href="#i-bell"/></svg>Send notification</button></div>
</div>
  </Fragment></div>
</div>
<script>
  import './toast-stack.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Toast stack ---------- */
/* each toast is the same size as the one in Toast: width, padding, type and icons */
.tsk-stack{position:relative;width:100%;max-width:380px;height:96px;isolation:isolate}
.tsk-stack.fan{height:var(--dm-fanh,96px)}
@media (hover:hover) and (pointer:fine){.tsk-stack:hover{height:var(--dm-fanh,96px)}}
.tsk-stack{transition:height .55s var(--dm-ease)}
.tsk-c{position:absolute;left:0;right:0;bottom:0;display:flex;align-items:center;gap:var(--dm-s-3);padding:var(--dm-s-3);background:var(--dm-surface);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow-toast);transition:transform .55s var(--dm-ease),opacity .45s var(--dm-ease),filter .45s;transform-origin:bottom center}
.tsk-c .g{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;flex:none}
.tsk-c .tx{flex:1;min-width:0;font-size:13px;line-height:1.35}
.tsk-c .tx b{font-weight:500;display:block}
.tsk-c .tx span{font-size:12px;color:var(--dm-muted)}
.tsk-c .t{font-size:11.5px;color:var(--dm-muted);align-self:flex-start;margin-top:2px}
/* the time sits at the right edge; the close button takes its place on hover */
.tsk-c .t{transition:opacity .2s}
.tsk-c .ib{position:absolute;top:50%;right:var(--dm-s-3);margin-top:-15px;opacity:0;transition:opacity .2s}
.tsk-c .ib:focus-visible{opacity:1}
@media (hover:hover) and (pointer:fine){.tsk-c:hover .ib{opacity:1}}
.tsk-c:has(.ib:focus-visible) .t{opacity:0}
@media (hover:hover) and (pointer:fine){.tsk-c:hover .t{opacity:0}}
/* Clean (lead, 18 Nov): each toast is the same small card as Toast's: content 16px in from every edge, ordinary 16px corners,
   no blur on the way in or behind the front one. Colour only for meaning: a passed check is green and a warning orange, on
   the icon alone; every other notification (a PR, synced frames, a draft) is grey, never a hue of its own. With no blur to
   hide it, a new toast turns opaque at once as it rises, so the words of the one it covers never show through. The deck is as
   tall as the toasts in it, growing as they arrive (--dm-deckh), instead of keeping room for three */
:root[data-style="clean"] .tsk-stack,:root [data-style="clean"] .tsk-stack,:root [data-style="clean"].tsk-stack{height:var(--dm-deckh,96px);transition:height var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] .tsk-stack.fan,:root [data-style="clean"] .tsk-stack.fan,:root [data-style="clean"].tsk-stack.fan{height:var(--dm-fanh,96px)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .tsk-stack:hover,:root [data-style="clean"] .tsk-stack:hover,:root [data-style="clean"].tsk-stack:hover{height:var(--dm-fanh,96px)}}
:root[data-style="clean"] .tsk-c,:root [data-style="clean"] .tsk-c,:root [data-style="clean"].tsk-c{gap:12px;padding:16px;border-radius:calc(12px * var(--dm-rk-l,var(--dm-rk)));filter:none!important;transition:transform var(--dm-t) var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .tsk-c .g,:root [data-style="clean"] .tsk-c .g,:root [data-style="clean"].tsk-c .g{width:20px;height:20px;background:none!important;color:var(--dm-fg2)!important}
:root[data-style="clean"] .tsk-c .g .i,:root [data-style="clean"] .tsk-c .g .i,:root [data-style="clean"].tsk-c .g .i{width:20px;height:20px}
:root[data-style="clean"] .tsk-c .g[data-tone="ok"],:root [data-style="clean"] .tsk-c .g[data-tone="ok"],:root [data-style="clean"].tsk-c .g[data-tone="ok"]{color:var(--dm-ok-mark)!important}
:root[data-style="clean"] .tsk-c .g[data-tone="warn"],:root [data-style="clean"] .tsk-c .g[data-tone="warn"],:root [data-style="clean"].tsk-c .g[data-tone="warn"]{color:var(--dm-warn-mark)!important}
:root[data-style="clean"] .tsk-c .g[data-tone="bad"],:root [data-style="clean"] .tsk-c .g[data-tone="bad"],:root [data-style="clean"].tsk-c .g[data-tone="bad"]{color:var(--dm-bad-mark)!important}
:root[data-style="clean"] .tsk-c .t,:root [data-style="clean"] .tsk-c .t,:root [data-style="clean"].tsk-c .t{font-variant-numeric:tabular-nums}
:root[data-style="clean"] .tsk-c .ib,:root [data-style="clean"] .tsk-c .ib,:root [data-style="clean"].tsk-c .ib{right:16px;width:28px;height:28px;margin-top:-14px}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, DM, I, html } from '../core/core.js';
DM.def('toast-stack', (r, c) => {
  const stack = $('.tsk-stack', r);
  // each with its tone (data-tone): Clean colours only the status ones, ok and warn, and shows the rest grey
  const pool = [
    ['ok','var(--dm-ok)','var(--dm-ok-bg)','Tests passed','42 of 42 in 38s','ok'],
    ['pr','var(--dm-merge)','var(--dm-merge-bg)','PR #412 is ready','Use shared spacing tokens','merge'],
    ['figma','var(--dm-pl)','var(--dm-pl-bg)','Frames synced','6 frames from Pricing.fig','purple'],
    ['warn','var(--dm-warn)','var(--dm-warn-bg)','Budget at 80%','1,600 of 2,000 credits','warn'],
    ['spark','var(--dm-pb)','var(--dm-pb-bg)','Draft written','Launch email, 2 subject lines','blue']
  ];
  // the stack fans out under the pointer, or while the focus is in it; a toast that can't be seen can't take the focus
  let items = [], n = 0, hover = false, focused = false;
  function layout(){
    const fan = hover || focused; let y = 0;
    const hs = items.map(it => it.offsetHeight);
    stack.style.setProperty('--dm-fanh', (hs.slice(-4).reduce((a, b) => a + b + 8, 0) - 8 || 96) + 'px');
    // the deck's own height: the front toast and the two that peek out above it (Clean sizes the stack to it)
    stack.style.setProperty('--dm-deckh', Math.ceil(items.slice(-3).reverse().reduce((m, it, k) => Math.max(m, it.offsetHeight * (1 - k * .05) + k * 10), 0)) + 'px');
    stack.classList.toggle('fan', fan);
    items.slice().reverse().forEach((it, i) => {
      if (fan){ it.style.transform = `translateY(${-y}px)`; it.style.opacity = i > 3 ? 0 : 1; it.style.filter = 'none'; if (i < 3) y += hs[items.length - 1 - i] + 8; }
      else { const k = Math.min(i, 3); it.style.transform = `translateY(${-k * 10}px) scale(${1 - k * .05})`; it.style.opacity = i > 2 ? 0 : 1 - k * .15; it.style.filter = i ? 'blur(.3px)' : 'none'; }
      it.style.zIndex = 100 - i; it.inert = fan ? i > 3 : i > 0;
    });
  }
  function add(){
    const p = pool[n++ % pool.length];
    const el = html(`<div class="tsk-c"><span class="g" data-tone="${p[5]}" style="color:${p[1]};background:${p[2]}">${I(p[0])}</span><div class="tx"><b>${p[3]}</b><span>${p[4]}</span></div><span class="t">now</span><button class="ib" aria-label="Dismiss" data-tip="Dismiss">${I('x')}</button></div>`);
    el.style.transform = 'translateY(24px) scale(.96)'; el.style.opacity = 0; el.style.filter = 'blur(6px)';
    stack.appendChild(el); items.push(el);
    $('.ib', el).onclick = () => { items = items.filter(x => x !== el); el.style.opacity = 0; el.style.transform += ' translateX(30px)'; setTimeout(() => el.remove(), 400); layout(); };
    if (items.length > 6){ const old = items.shift(); old.remove(); }
    requestAnimationFrame(() => requestAnimationFrame(layout));
    items.forEach((it, i) => { if (i < items.length - 1){ const t = $('.t', it); t.textContent = (items.length - 1 - i) * 2 + 'm'; } });
  }
  c.on(stack, 'pointerenter', () => { hover = true; layout(); });
  c.on(stack, 'pointerleave', () => { hover = false; layout(); });
  c.on(stack, 'focusin', () => { if (!focused){ focused = true; layout(); } });
  c.on(stack, 'focusout', e => { if (!stack.contains(e.relatedTarget)){ focused = false; layout(); } });
  $('.tsk-add', r).onclick = add;
  c.run(async () => {
    for (let i = 0; i < 3; i++){ await c.wait(i ? 700 : 400); add(); }
    // then a new one now and then, held back while the stack is fanned out under the pointer, until you take over
    for (;;){ await c.step(3800); if (!hover && !focused) add(); }
  });
});
